#define EXERCISE_H
#include <stddef.h>
#include <stdbool.h>
#include <stdint.h>
typedef struct {int year,month,day;const char *description;int64_t change;} entry;
char *format_entries(const char *currency,const char *locale,const entry *entries,size_t n);
#endif

