#include "exercise.h"
#include <assert.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include <stdio.h>
static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
entry e[]={{2015,1,1,"Buy present",-1000},{2015,1,2,"Get present",123456}};char*s=format_entries("USD","en_US",e,2);assert(strstr(s,"01/01/2015 | Buy present               |      ($10.00)"));assert(strstr(s,"$1,234.56 "));free(s);s=format_entries("EUR","nl_NL",e,2);assert(strstr(s,"01-01-2015")&&strstr(s,"€ -10,00 "));free(s);s=format_entries("USD","en_US",NULL,0);assert(!strcmp(s,"Date       | Description               | Change       "));free(s);
{entry values[]={{0,0,0,NULL,0}};char*actual=format_entries("USD","en_US",values,0);assert(!strcmp(actual,"Date       | Description               | Change       "));free(actual);}
{entry values[]={{2015,1,1,"Buy present",-1000}};char*actual=format_entries("USD","en_US",values,1);assert(!strcmp(actual,"Date       | Description               | Change       \n01/01/2015 | Buy present               |      ($10.00)"));free(actual);}
{entry values[]={{2015,1,2,"Get present",1000},{2015,1,1,"Buy present",-1000}};char*actual=format_entries("USD","en_US",values,2);assert(!strcmp(actual,"Date       | Description               | Change       \n01/01/2015 | Buy present               |      ($10.00)\n01/02/2015 | Get present               |       $10.00 "));free(actual);}
{entry values[]={{2015,1,1,"Something",0},{2015,1,1,"Something",-1},{2015,1,1,"Something",1}};char*actual=format_entries("USD","en_US",values,3);assert(!strcmp(actual,"Date       | Description               | Change       \n01/01/2015 | Something                 |       ($0.01)\n01/01/2015 | Something                 |        $0.00 \n01/01/2015 | Something                 |        $0.01 "));free(actual);}
{entry values[]={{2015,1,1,"Freude schoner Gotterfunken",-123456}};char*actual=format_entries("USD","en_US",values,1);assert(!strcmp(actual,"Date       | Description               | Change       \n01/01/2015 | Freude schoner Gotterf... |   ($1,234.56)"));free(actual);}
{entry values[]={{2015,1,1,"Buy present",-1000}};char*actual=format_entries("EUR","en_US",values,1);assert(!strcmp(actual,"Date       | Description               | Change       \n01/01/2015 | Buy present               |      (€10.00)"));free(actual);}
{entry values[]={{2015,3,12,"Buy present",123456}};char*actual=format_entries("USD","nl_NL",values,1);assert(!strcmp(actual,"Datum      | Omschrijving              | Verandering  \n12-03-2015 | Buy present               |   $ 1.234,56 "));free(actual);}
{entry values[]={{2015,3,12,"Buy present",123456}};char*actual=format_entries("EUR","nl_NL",values,1);assert(!strcmp(actual,"Datum      | Omschrijving              | Verandering  \n12-03-2015 | Buy present               |   € 1.234,56 "));free(actual);}
{entry values[]={{2015,3,12,"Buy present",-12345}};char*actual=format_entries("USD","nl_NL",values,1);assert(!strcmp(actual,"Datum      | Omschrijving              | Verandering  \n12-03-2015 | Buy present               |    $ -123,45 "));free(actual);}
{entry values[]={{2015,3,12,"Buy present",-12345}};char*actual=format_entries("USD","en_US",values,1);assert(!strcmp(actual,"Date       | Description               | Change       \n03/12/2015 | Buy present               |     ($123.45)"));free(actual);}
